(()=>{'use strict';const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const E=window.AcademyEngines,content=window.ACADEMY_MENTORSHIP;let context=null;const STAGE_NAMES={BRIEF:'Understand the task',LEARN:'Learn the method',INVESTIGATE:'Check the facts',TRY:'Try a small part',BUILD:'Do the complete job',BREAK:'Test a failure',FIX:'Correct the problem',TEST:'Check the result',EXPLAIN:'Explain your decision',DEFEND:'Answer review questions',SHIP:'Hand over the work',EVIDENCE:'Prepare the review pack'};
const examples={records:{prompt:'A team has a reviewed file and a newer unreviewed draft. Which copy should it send?',choices:['The newest filename','The reviewed copy'],correct:'The reviewed copy',explanation:'The recorded review is the source of authority. A newer filename alone does not establish approval.'},document:{prompt:'Which handover helps a colleague act without guessing?',choices:['“Everything is done.”','Named owner, action, due time and check'],correct:'Named owner, action, due time and check',explanation:'A useful handover explains the next action and how the recipient can check it.'},html:{prompt:'You press Add once. The counter starts at zero. What should you see?',choices:['1','0'],correct:'1',explanation:'The click handler reads the current number, adds one and changes the displayed value.'},api:{prompt:'A different customer asks to read Alice’s booking. Ownership checks are on. What should happen?',choices:['200 / allow the record','403 / refuse access'],correct:'403 / refuse access',explanation:'The customer identity does not match the record owner, so the service must refuse the request.'},sql:{prompt:'How many orders in the supplied table have status paid?',choices:['1','3'],correct:'1',explanation:'Only O1 has paid status. A WHERE condition keeps that row and excludes the two pending rows.'},permissions:{prompt:'A customer can read only their own records. Can they read another customer’s booking?',choices:['Allow','Deny'],correct:'Deny',explanation:'The allowed action must also match the allowed record scope.'},ledger:{prompt:'The two sides are 80 and 70. Can this posting be accepted as balanced?',choices:['Accept','Reject'],correct:'Reject',explanation:'The amounts differ by 10. A balanced posting needs equal sides as well as the right accounts.'},events:{prompt:'Revision 3 is current. Revision 2 arrives late. What should the handler do?',choices:['Replace 3 with 2','Keep 3 and reject 2'],correct:'Keep 3 and reject 2',explanation:'Accept only a revision newer than the current one. Arrival time does not make an old version current.'},uploads:{prompt:'A file is named notes.pdf but contains ordinary text. Should the basic PDF check accept it?',choices:['Accept the extension','Reject the missing PDF signature'],correct:'Reject the missing PDF signature',explanation:'The content must begin with the expected PDF signature. Its filename alone is not enough.'},workflow:{prompt:'An order has no identifier. What should validation do before any external action?',choices:['Continue anyway','Stop and report the missing input'],correct:'Stop and report the missing input',explanation:'Missing required input must stop the process before an action can affect the real world.'}};
function state(d){if(!d.coach)d.coach={step:0,mode:'Guided',prediction:'',revealed:false,questions:[],demo:{},answer:''};return d.coach}
const button=(text,action,extra='')=>`<button class="btn sm" data-mentor="${action}" ${extra}>${text}</button>`;
function render(m,d,stage){context={m,d,stage};const c=state(d),lesson=content[m.id],s=lesson.stages[stage],supported='speechSynthesis'in window;return `<section class="mentor" aria-label="Step-by-step professional guide"><div class="mentor-heading"><img src="brand/mark-academy.webp" alt="" width="40" height="40"><div><strong>Your task guide</strong><span>${esc(s.title)}</span></div><div class="mentor-controls">${supported?button('Listen to this step','listen')+button('Stop voice','stop'):''}${button(c.mode==='Guided'?'Use independent mode':'Use guided mode','mode')}</div></div><p class="mentor-speech">${esc(c.mode==='Guided'?s.spoken:s.nextAction)}</p><div class="mentor-next"><b>Next action</b><span>${esc(s.nextAction)}</span></div>${d.lastRun&&['TRY','BUILD','FIX','TEST'].includes(stage)?feedback(m,d):''}<div class="mentor-questions">${button('Explain why this matters','why')}${button('Show a common mistake','mistake')}${button('What should I do next?','next')}</div>${c.question?`<div class="mentor-answer" role="status">${esc(c.question)}</div>`:''}</section>`}
function feedback(m,d){const r=d.lastRun,failed=r.checks.filter(x=>!x.pass);return `<div class="mentor-feedback ${r.pass?'positive':''}" role="status"><b>${r.pass?'Your current checks passed.':'Let’s resolve the first failed check.'}</b><p>${r.pass?'Before moving on, inspect what passed and keep the normal and failure-case results. '+(r.requiresReview?'These checks confirm structure; professional quality still needs a qualified review.':'A local check is learning evidence, not independent assessment.'):(failed[0]?failed[0].name+': '+(failed[0].detail||'Compare this result with the source facts and change one thing before rerunning.'):'Rerun the current work to get a usable result.')}</p>${!r.pass?button('Take me to the next correction','focus'):''}</div>`}
function lesson(m,d){context={m,d,stage:'LEARN'};const c=state(d),a=content[m.id],ex=examples[m.engine],step=a.steps[c.step];return `<section class="lesson-player"><div class="lesson-toolbar"><h3>${esc(a.methodTitle)}</h3><span>Explanation ${c.step+1} of ${a.steps.length}</span></div><h4>${esc(step.title)}</h4><p class="lesson-narration">${esc(step.body)}</p><div class="row">${button('Previous explanation','previous',c.step===0?'disabled':'')}${button('Next explanation','next-step',c.step===a.steps.length-1?'disabled':'')}${'speechSynthesis'in window?button('Read this explanation aloud','listen-lesson'):''}</div><div class="prediction"><h4>Before we run it, what do you expect?</h4><p>${esc(ex.prompt)}</p><div class="row">${ex.choices.map(answer=>button(answer,'predict',`data-choice="${esc(answer)}" aria-pressed="${c.prediction===answer}"`)).join('')}</div>${c.prediction?button('Check my prediction','reveal'):''}${c.revealed?`<p class="prediction-feedback" role="status"><b>${c.prediction===ex.correct?'Your prediction matches the rule.':'Let’s check the rule together.'}</b> ${esc(ex.explanation)}</p>`:''}</div><details class="mentor-demo" ${c.revealed?'open':''}><summary>Run the separate teaching example</summary><p>This is a demonstration. It does not fill in your assignment or count as a passed mission.</p>${demoUI(m,c)}<div id="mentor-demo-output" class="demo-output" aria-live="polite">${c.demoOutput?output(c.demoOutput):'Run the example to see what actually happens.'}</div></details><div class="teach-back"><h4>Explain it back</h4><p>In your own words, what rule will you use and what mistake will you check for?</p><label for="mentor-answer">Your explanation</label><textarea id="mentor-answer" data-coach-field="answer">${esc(c.answer)}</textarea>${button('Check my explanation checklist','teach-back')}${c.selfCheck?`<p role="status">${esc(c.selfCheck)}</p>`:''}</div><div class="row">${button('Open my own work area','open-work')}<span class="caption">The teaching example stays separate from your work and review evidence.</span></div></section>`}
function input(k,label,v,type='text'){return `<div class="field"><label for="demo-${k}">${label}</label><input id="demo-${k}" type="${type}" data-demo-field="${k}" value="${esc(v)}"></div>`}function select(k,label,options,v){return `<div class="field"><label for="demo-${k}">${label}</label><select id="demo-${k}" data-demo-field="${k}">${options.map(o=>`<option ${o===v?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`}function check(k,label,v){return `<label class="checklabel"><input type="checkbox" data-demo-field="${k}" ${v?'checked':''}>${label}</label>`}
function demoUI(m,c){const v=c.demo;
if(m.engine==='records')return `${select('file','Choose the file',['New unreviewed draft','Earlier reviewed copy'],v.file||'New unreviewed draft')}${button('Check the handover choice','run-demo')}`;
if(m.engine==='document')return `${select('handover','Choose the handover',['Everything is done.','Maya owns the revised schedule; confirm access by 15:00 and record the response.'],v.handover||'Everything is done.')}${button('Inspect the handover','run-demo')}`;
if(m.engine==='html')return `<label for="demo-code">Editable demonstration HTML and JavaScript</label><textarea id="demo-code" data-demo-field="code" class="code demo-code">${esc(v.code||'<button id="add">Add</button> <output id="count" aria-live="polite">0</output>\n<script>\nlet total = 0;\ndocument.getElementById("add").onclick = () => {\n  total = total + 1;\n  document.getElementById("count").textContent = total;\n};\n</script>')}</textarea>${button('Run interactive example','run-demo')}<iframe id="mentor-preview" class="preview demo-preview" sandbox="allow-scripts" title="Isolated teaching example" srcdoc="${esc(c.demoHTML||'')}"></iframe><p class="caption">Press Add inside the preview. Inspect the count, then edit the example and run it again.</p>`;
if(m.engine==='api')return `${select('actor','Who is asking?',['bob','alice'],v.actor||'bob')}${check('ownership','Enforce record ownership',v.ownership!==false)}${button('Send teaching request','run-demo')}`;
if(m.engine==='sql')return `<label for="demo-code">Teaching query</label><textarea id="demo-code" data-demo-field="code" class="demo-code">${esc(v.code||"SELECT id, status FROM orders WHERE status = 'paid';")}</textarea>${button('Execute teaching query','run-demo')}`;
if(m.engine==='permissions')return `${select('owner','Whose record?',['Another customer’s','The signed-in customer’s'],v.owner||'Another customer’s')}${button('Check the record boundary','run-demo')}`;
if(m.engine==='ledger')return `<div class="cols">${input('debit','First side',v.debit??'80')}${input('credit','Second side',v.credit??'70')}</div>${button('Check the balance','run-demo')}`;
if(m.engine==='events')return `${check('monotonic','Keep the newest revision',v.monotonic!==false)}${check('deduplicate','Reject repeated event IDs',v.deduplicate!==false)}${button('Process teaching feed','run-demo')}`;
if(m.engine==='uploads')return `${select('fixture','Choose a fictional file',['Text pretending to be a PDF','Valid small CSV','Unsupported executable filename'],v.fixture||'Text pretending to be a PDF')}${button('Inspect teaching file','run-demo')}`;
return `${check('valid','Include an order ID',v.valid===true)}${button('Run teaching workflow','run-demo')}`}
function output(v){return `<pre>${esc(JSON.stringify(v,null,2))}</pre>`}
async function demo(m,c){const v=c.demo;if(m.engine==='records')return {chosen:v.file||'New unreviewed draft',approved:v.file==='Earlier reviewed copy',decision:v.file==='Earlier reviewed copy'?'Send the reviewed copy and record its owner.':'Hold the unreviewed draft; a newer filename is not approval.'};if(m.engine==='document'){const text=v.handover||'Everything is done.';return{handover:text,ownerNamed:/Maya/.test(text),nextAction:/confirm/.test(text),dueTime:/15:00/.test(text),checkRecorded:/record the response/.test(text),scope:'Demonstration checklist only; no professional quality grade.'}}if(m.engine==='api')return E.request(E.apiSeed(),{method:'GET',path:'/bookings/BK-100',actor:v.actor||'bob'},{ownership:v.ownership!==false});if(m.engine==='sql'){try{return{query:v.code||"SELECT id, status FROM orders WHERE status = 'paid';",rows:E.query(v.code||"SELECT id, status FROM orders WHERE status = 'paid';")}}catch(e){return{error:e.message}}}if(m.engine==='permissions')return{requestedRecord:v.owner||'Another customer’s',scope:'Own records only',decision:v.owner==='The signed-in customer’s'?'Allow':'Deny'};if(m.engine==='ledger'){const a=E.calculate(v.debit??80),b=E.calculate(v.credit??70);return{firstSide:a,secondSide:b,difference:a-b,decision:Number.isFinite(a)&&a>0&&Math.abs(a-b)<.005?'Balanced; now also check accounts and duplicate protection.':'Reject: unequal or invalid amounts.'}}if(m.engine==='events')return E.events(m,{fields:{monotonic:v.monotonic!==false,deduplicate:v.deduplicate!==false}}).output;if(m.engine==='uploads'){const fixture=v.fixture||'Text pretending to be a PDF';const f=fixture==='Valid small CSV'?new File(['item,amount\nTea,12'],'case.csv',{type:'text/csv'}):fixture==='Unsupported executable filename'?new File(['fictional text only'],'example.exe'):new File(['This is ordinary text, not PDF content.'],'notes.pdf',{type:'application/pdf'});return E.validateFile(f)}if(m.engine==='workflow')return E.workflow({...m,variant:v.valid?'normal':'invalid'},{code:JSON.stringify({steps:['validate','deduplicate','human_approval','record_result'],maxRetries:2,retryDelaySeconds:3,deadLetterOwner:'Operations lead'})}).output;return null}
function stop(){if('speechSynthesis'in window)window.speechSynthesis.cancel()}function speak(text){if(!('speechSynthesis'in window))return;stop();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='en-GB';utterance.rate=.92;utterance.onerror=()=>{const el=document.getElementById('mentor-demo-output');if(el)el.textContent='Voice playback is unavailable. The complete explanation remains on screen.'};window.speechSynthesis.speak(utterance)}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-mentor]');if(!button||!context||button.disabled)return;const {m,d,stage}=context,c=state(d),a=content[m.id];try{switch(button.dataset.mentor){case'mode':c.mode=c.mode==='Guided'?'Independent':'Guided';break;case'listen':speak(a.stages[stage].spoken);return;case'listen-lesson':speak(a.steps[c.step].body);return;case'stop':stop();return;case'previous':c.step=Math.max(0,c.step-1);stop();break;case'next-step':c.step=Math.min(2,c.step+1);stop();break;case'predict':c.prediction=button.dataset.choice;c.revealed=false;break;case'reveal':c.revealed=true;break;case'why':c.question=a.introduction+' '+a.principle;break;case'mistake':c.question=a.commonMistake;break;case'next':c.question=a.stages[stage].nextAction;break;case'open-work':window.AcademyMentorBridge.openStage('TRY');return;case'focus':{const failed=d.lastRun?.checks.find(x=>!x.pass),field=m.fields?.find(f=>f.label===failed?.name);const target=field?document.getElementById('field-'+field.key):document.getElementById('code')||document.querySelector('.stagebody input,.stagebody select,.stagebody textarea');target?.focus();target?.scrollIntoView({behavior:'smooth',block:'center'});return}case'teach-back':{const words=c.answer.trim().split(/\s+/).filter(Boolean).length;c.selfCheck=words<15?'Add a little more detail: name the rule, the case fact you will use and the failure you will check.':'Your explanation has enough detail for a self-check. Compare it with the rule above: did you name the source fact, the action and the failure check? This is a writing checklist, not a reviewed grade.';break}case'run-demo':{button.disabled=true;if(m.engine==='html'){const f=document.getElementById('mentor-preview'),code=c.demo.code||document.getElementById('demo-code').value;c.demoHTML='<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; script-src \'unsafe-inline\'; style-src \'unsafe-inline\'; img-src data:; form-action \'none\'; base-uri \'none\'"><style>body{font:16px system-ui;padding:18px}button{padding:10px 20px}output{margin-left:16px}</style>'+code;f.srcdoc=c.demoHTML;c.demoOutput={status:'Interactive preview started. Press Add and compare the displayed count. The example restarts when you change lesson controls.'};document.getElementById('mentor-demo-output').innerHTML=output(c.demoOutput)}else{const result=await demo(m,c);if(context.m.id!==m.id)return;c.demoOutput=result;document.getElementById('mentor-demo-output').innerHTML=output(result)}window.AcademyMentorBridge.save();button.disabled=false;return}}
window.AcademyMentorBridge.save();window.AcademyMentorBridge.render();}catch(e){const el=document.getElementById('mentor-demo-output');if(el)el.textContent='The example could not run: '+e.message+' You can still read the explanation.';button.disabled=false}});
document.addEventListener('input',event=>{if(!context)return;const el=event.target,c=state(context.d);if(el.dataset.demoField){c.demo[el.dataset.demoField]=el.type==='checkbox'?el.checked:el.value;c.demoOutput=null;window.AcademyMentorBridge.save()}if(el.dataset.coachField){c[el.dataset.coachField]=el.value;window.AcademyMentorBridge.save()}});window.addEventListener('pagehide',stop);window.AcademyMentor={render,lesson,stageNames:STAGE_NAMES,stop,demo};})();
